Insert into CTJOURNAL_NAME (JOURNAL_NAME,SHORT_NAME,ISSN,START_YEAR,END_YEAR,REMARKS) values ('Catalogue of American Amphibians and Reptiles','Catalogue','Print ISSN: 2325-4882; Online ISSN: 2325-5021',1963,null,'Per SSAR website: "The Catalogue (Print ISSN: 2325-4882; Online ISSN: 2325-5021) consists of accounts of taxa prepared by specialists, including synonymy, description, diagnosis, phylogenetic relationships, published descriptions, illustrations, distribution map, and comprehensive list of literature for each taxon. Over 900 accounts have been published since the initiation of the series in 1963. The series covers amphibians and reptiles of the entire Western Hemisphere. Previously, accounts were published as loose-leaf separates; beginning in 2013 accounts are published as on-line PDFs.  All accounts are open access and are available for free download at the University of Texas Library Repository."');
