Insert into CTJOURNAL_NAME (JOURNAL_NAME,SHORT_NAME,ISSN,START_YEAR,END_YEAR,REMARKS) values ('Deinsea','Deinsea','0923-9308',1994,2016,'Annual of the Natural History Museum Rotterdam.    Volumes 1 - 14 (1994 - 2010) published in print as Deinsea (ISSN 0923-9308). Volume 15 (2012) onwards, Deinsea published online only (2468-8983), renamed in 2016 as Deinsea: Online Journal of the Natural History Museum Rotterdam.  Use that record for publications from 2016 on.  Note that the Print/Online ISSN numbers don''t exactly match the name change.');
Insert into CTJOURNAL_NAME (JOURNAL_NAME,SHORT_NAME,ISSN,START_YEAR,END_YEAR,REMARKS) values ('Deinsea: Online Journal of the Natural History Museum Rotterdam','Deinsea','2468-8983',2016,null,'Annual of the Natural History Museum Rotterdam.    Volumes 1 - 14 (1994 - 2010) published in print as Deinsea. Volume 15 (2012) onwards, Deinsea published online only, renamed as Deinsea: Online Journal of the Natural History Museum Rotterdam in 2016.  Use this record for Publications from 2016 on, the Deinsea record for publications before that.  Note that the print/online ISSN change doesn''t correspond to the name change.');
